// Hand-written bridge between the `uni-data-value` envelope a Mudu host
// passes across the procedure byte pipe and the MessagePack wire shape the
// mgen-generated AssemblyScript record codecs (the `XxxCodec` classes in the
// files carrying the "Generated by mudu_gen" header) consume and produce.
//
// A user-defined record argument travels as a UniDataValue record case:
// field entries in WIT declaration order, field names possibly empty (the
// host drops them — positional semantics). `recordFieldValues` transcodes
// that envelope into the integer-keyed MessagePack map (1-based field
// numbers) the generated `XxxCodec.decode` reads; `recordFromFieldValues`
// is the symmetric parse of the map a generated `XxxCodec.encode` writes,
// producing the record-case envelope for a procedure return value (field
// names empty, like the host's).
//
// The host's transactable scalar vocabulary (`uni_to`/`uni_from` in
// mudu_binding) has no Bool/U8..U32/U64 cases: booleans cross as i32 (0/1 —
// the desc declares them I32, the same family the procedure scalar table
// uses), unsigned 8-32-bit integers as i32, and u64 as i64. On the encode
// side this bridge emits exactly that vocabulary; on the decode side the
// leniency lives in the shared runtime (`MpackReader.readBool` accepts the
// i32 0/1 form), so the generated codecs decode host-supplied records
// unchanged. Byte-typed values (`blob`/`binary` record fields) keep the
// record-context wire form: a plain MessagePack ARRAY of u8.
//
// Decode stays lenient end to end: the generated decoders skip field numbers
// they do not declare and default the missing ones. On encode, a field the
// generated encoder omitted (a null WIT `option<T>` field) is gap-filled
// with the Null scalar so declaration positions are preserved (trailing
// omitted slots cannot be recovered and shrink the record, which the host
// decodes leniently).

import { MpackReader, MpackWriter } from "./mpack";
import {
  UniDataValue,
  UniDataValueArray,
  UniDataValueBinary,
  UniDataValueField,
  UniDataValueKind,
  UniDataValueRecord,
  UniDataValueScalar,
} from "./generated/UniDataValue";
import {
  UniScalarValue,
  UniScalarValueBlob,
  UniScalarValueBool,
  UniScalarValueChar,
  UniScalarValueDate,
  UniScalarValueF32,
  UniScalarValueF64,
  UniScalarValueI16,
  UniScalarValueI32,
  UniScalarValueI64,
  UniScalarValueI8,
  UniScalarValueI128,
  UniScalarValueKind,
  UniScalarValueNull,
  UniScalarValueNumeric,
  UniScalarValueString,
  UniScalarValueTime,
  UniScalarValueTimestamp,
  UniScalarValueTimestampTz,
  UniScalarValueU16,
  UniScalarValueU32,
  UniScalarValueU64,
  UniScalarValueU8,
  UniScalarValueU128,
} from "./generated/UniScalarValue";

// Unwrap a UniDataValue record-case envelope into the integer-keyed
// MessagePack map bytes (position i becomes key i+1, the WIT declaration
// order) a generated `XxxCodec.decode` consumes:
//
//   const profile = ProfileCodec.decode(new MpackReader(recordFieldValues(v)));
//
// Field values transcode to the plain MessagePack wire model recursively
// (nested records become nested integer-keyed maps, arrays become
// MessagePack arrays, byte strings become u8 arrays, the Null scalar
// becomes nil). A non-record input is an error.
export function recordFieldValues(value: UniDataValue): Uint8Array {
  if (value.kind != UniDataValueKind.Record) {
    throw new Error("expected a UniDataValue record, got kind " + value.kind.toString());
  }
  const fields = (value as UniDataValueRecord).inner;
  const writer = new MpackWriter();
  writer.writeMapHeader(fields.length as u32);
  for (let i = 0; i < fields.length; i++) {
    writer.writeU64((i + 1) as u64);
    writeDatumWire(fields[i].field_value, writer);
  }
  return writer.toBytes();
}

// Parse the integer-keyed MessagePack map bytes a generated
// `XxxCodec.encode` produces and wrap the positional field values in the
// UniDataValue record-case envelope the host expects back:
//
//   const writer = new MpackWriter();
//   ProfileCodec.encode(result, writer);
//   const datum = recordFromFieldValues(writer.toBytes());
//
// Field numbers are 1-based; a missing slot (an omitted option field)
// encodes as the Null scalar so declaration positions are preserved. Keys
// beyond the map's maximum are skipped like the generated decoders do;
// trailing omitted slots shrink the record. Field values convert to the
// host's transactable scalar vocabulary (see the module comment above):
// booleans become I32 (0/1), integers become I32 or I64 by range, and a
// u64 value beyond i64.MAX is an error (the host cannot carry it).
export function recordFromFieldValues(fieldMapBytes: Uint8Array): UniDataValue {
  const reader = new MpackReader(fieldMapBytes);
  return readWireRecord(reader);
}

// Whether the datum is the Null scalar (the wire form of a null WIT
// `option<T>` procedure parameter).
export function isNullDatum(value: UniDataValue): bool {
  return (
    value.kind == UniDataValueKind.Scalar &&
    (value as UniDataValueScalar).inner.kind == UniScalarValueKind.Null
  );
}

// ---- envelope -> wire ----

function writeDatumWire(value: UniDataValue, writer: MpackWriter): void {
  switch (value.kind) {
    case UniDataValueKind.Scalar:
      writeScalarWire((value as UniDataValueScalar).inner, writer);
      return;
    case UniDataValueKind.Array: {
      const items = (value as UniDataValueArray).inner;
      writer.writeArrayHeader(items.length as u32);
      for (let i = 0; i < items.length; i++) {
        writeDatumWire(items[i], writer);
      }
      return;
    }
    case UniDataValueKind.Record: {
      const fields = (value as UniDataValueRecord).inner;
      writer.writeMapHeader(fields.length as u32);
      for (let i = 0; i < fields.length; i++) {
        writer.writeU64((i + 1) as u64);
        writeDatumWire(fields[i].field_value, writer);
      }
      return;
    }
    case UniDataValueKind.Binary:
      writeBytesAsArray((value as UniDataValueBinary).inner, writer);
      return;
    default:
      throw new Error("unknown UniDataValue kind " + value.kind.toString());
  }
}

function writeScalarWire(scalar: UniScalarValue, writer: MpackWriter): void {
  switch (scalar.kind) {
    case UniScalarValueKind.Null:
      writer.writeNil();
      return;
    case UniScalarValueKind.Bool:
      writer.writeBool((scalar as UniScalarValueBool).inner);
      return;
    case UniScalarValueKind.U8:
      writer.writeU64((scalar as UniScalarValueU8).inner as u64);
      return;
    case UniScalarValueKind.U16:
      writer.writeU64((scalar as UniScalarValueU16).inner as u64);
      return;
    case UniScalarValueKind.U32:
      writer.writeU64((scalar as UniScalarValueU32).inner as u64);
      return;
    case UniScalarValueKind.U64:
      writer.writeU64((scalar as UniScalarValueU64).inner);
      return;
    case UniScalarValueKind.I8:
      writer.writeI64((scalar as UniScalarValueI8).inner as i64);
      return;
    case UniScalarValueKind.I16:
      writer.writeI64((scalar as UniScalarValueI16).inner as i64);
      return;
    case UniScalarValueKind.I32:
      writer.writeI64((scalar as UniScalarValueI32).inner as i64);
      return;
    case UniScalarValueKind.I64:
      writer.writeI64((scalar as UniScalarValueI64).inner);
      return;
    case UniScalarValueKind.F32:
      writer.writeF32((scalar as UniScalarValueF32).inner);
      return;
    case UniScalarValueKind.F64:
      writer.writeF64((scalar as UniScalarValueF64).inner);
      return;
    case UniScalarValueKind.Char:
      writer.writeString((scalar as UniScalarValueChar).inner);
      return;
    case UniScalarValueKind.String:
      writer.writeString((scalar as UniScalarValueString).inner);
      return;
    case UniScalarValueKind.Numeric:
      writer.writeString((scalar as UniScalarValueNumeric).inner);
      return;
    case UniScalarValueKind.Date:
      writer.writeString((scalar as UniScalarValueDate).inner);
      return;
    case UniScalarValueKind.Time:
      writer.writeString((scalar as UniScalarValueTime).inner);
      return;
    case UniScalarValueKind.Timestamp:
      writer.writeString((scalar as UniScalarValueTimestamp).inner);
      return;
    case UniScalarValueKind.TimestampTz:
      writer.writeString((scalar as UniScalarValueTimestampTz).inner);
      return;
    case UniScalarValueKind.Blob:
      writeBytesAsArray((scalar as UniScalarValueBlob).inner, writer);
      return;
    case UniScalarValueKind.U128:
      // 128-bit scalars have no generated-codec record field form (mgen
      // rejects them for AssemblyScript); keep the uniform byte-array shape.
      writeBytesAsArray((scalar as UniScalarValueU128).inner, writer);
      return;
    case UniScalarValueKind.I128:
      writeBytesAsArray((scalar as UniScalarValueI128).inner, writer);
      return;
    default:
      throw new Error("unknown UniScalarValue kind " + scalar.kind.toString());
  }
}

// Record-context byte strings are plain MessagePack arrays of u8 (the
// pinned host form), never MessagePack bin.
function writeBytesAsArray(bytes: Uint8Array, writer: MpackWriter): void {
  writer.writeArrayHeader(bytes.length as u32);
  for (let i = 0; i < bytes.length; i++) {
    writer.writeU64(bytes[i]);
  }
}

// ---- wire -> envelope ----

function readWireRecord(reader: MpackReader): UniDataValue {
  const byKey = new Map<u64, UniDataValue>();
  let maxKey: u64 = 0;
  const count = reader.readMapHeader();
  for (let i: u32 = 0; i < count; i++) {
    // Mirrors the generated decoders' lenient key handling: a non-integer
    // key collapses to 0 and its value is skipped.
    const key = reader.readMapKey();
    if (key == 0) {
      reader.skipValue();
      continue;
    }
    byKey.set(key, readWireDatum(reader));
    if (key > maxKey) {
      maxKey = key;
    }
  }
  const record = new UniDataValueRecord();
  const fields = new Array<UniDataValueField>(maxKey as i32);
  for (let i = 0; i < (maxKey as i32); i++) {
    const field = new UniDataValueField();
    field.field_name = "";
    const key = (i + 1) as u64;
    field.field_value = byKey.has(key) ? byKey.get(key) : nullDatum();
    fields[i] = field;
  }
  record.inner = fields;
  return record;
}

function readWireDatum(reader: MpackReader): UniDataValue {
  const code = reader.peekCode();
  if (code == 0xc0) {
    reader.tryNil();
    return nullDatum();
  }
  if (code == 0xc2 || code == 0xc3) {
    // the host vocabulary has no Bool: booleans cross as i32 (0/1)
    return scalarI32(reader.readBool() ? 1 : 0);
  }
  if (code <= 0x7f || code >= 0xe0 || (code >= 0xcc && code <= 0xd3)) {
    const v = reader.readI64();
    if (v >= i32.MIN_VALUE && v <= i32.MAX_VALUE) {
      return scalarI32(v as i32);
    }
    return scalarI64(v);
  }
  if (code == 0xca) {
    const scalar = new UniScalarValueF32();
    scalar.inner = reader.readF32();
    return scalarOf(scalar);
  }
  if (code == 0xcb) {
    const scalar = new UniScalarValueF64();
    scalar.inner = reader.readF64();
    return scalarOf(scalar);
  }
  if ((code & 0xe0) == 0xa0 || (code >= 0xd9 && code <= 0xdb)) {
    const scalar = new UniScalarValueString();
    scalar.inner = reader.readString();
    return scalarOf(scalar);
  }
  if (code >= 0xc4 && code <= 0xc6) {
    const scalar = new UniScalarValueBlob();
    scalar.inner = reader.readBin();
    return scalarOf(scalar);
  }
  if ((code & 0xf0) == 0x90 || code == 0xdc || code == 0xdd) {
    const n = reader.readArrayHeader() as i32;
    const items = new Array<UniDataValue>(n);
    for (let i = 0; i < n; i++) {
      items[i] = readWireDatum(reader);
    }
    const value = new UniDataValueArray();
    value.inner = items;
    return value;
  }
  if ((code & 0xf0) == 0x80 || code == 0xde || code == 0xdf) {
    return readWireRecord(reader);
  }
  throw new Error("unsupported MessagePack marker 0x" + code.toString(16));
}

// ---- small datum constructors ----

function nullDatum(): UniDataValue {
  return scalarOf(new UniScalarValueNull());
}

function scalarI32(v: i32): UniDataValue {
  const scalar = new UniScalarValueI32();
  scalar.inner = v;
  return scalarOf(scalar);
}

function scalarI64(v: i64): UniDataValue {
  const scalar = new UniScalarValueI64();
  scalar.inner = v;
  return scalarOf(scalar);
}

function scalarOf(scalar: UniScalarValue): UniDataValue {
  const value = new UniDataValueScalar();
  value.inner = scalar;
  return value;
}
